import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {useRouteParams} from '@github-ui/react-core/future/use-route-params'
import {businessPatternConfigsPageRoute} from './pattern-configs-page-route'
import {PatternConfigsPage} from './PatternConfigsPage'

export function BusinessRoute() {
  const payload = useRouteQuery(businessPatternConfigsPageRoute, 'mainQuery').data
  const {slug} = useRouteParams(businessPatternConfigsPageRoute)
  return (
    <PatternConfigsPage
      payload={payload}
      ownerType="biz"
      updatePath={businessPatternConfigsPageRoute.generatePath({slug})}
    />
  )
}

try{ BusinessRoute.displayName ||= 'BusinessRoute' } catch {}